using Clipbox.Win32.Native;

namespace Clipbox.Win32.LLHooks
{
    public class KeyboardEventArgs
    {
        public NativeEnums.KeyboardMessages KeyboardAction { get; set; }
        public NativeEnums.Keys Key { get; set; }
        public bool CancelEvent { get; set; }

        /// <summary>
        /// True if the event is generated by some software,
        /// not by the keyboard device itself
        /// </summary>
        public bool IsInjected { get; set; }

        public KeyboardEventArgs(NativeEnums.Keys key, NativeEnums.KeyboardMessages action, bool isInjected)
        {
            Key = key;
            KeyboardAction = action;
            IsInjected = isInjected;
        }
    }
}
